#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <sys/wait.h>
#include <sys/types.h>
#include <sys/sysinfo.h>
#include <netinet/in.h>
#include <fcntl.h>
#include <errno.h>
#define PORT 5000
#define BUF_SIZE 16384
static pid_t engine_pid=-1;
static const char *csv_file="os_stresslab_results.csv";
static void send_response(int fd,int status,const char*type,const char*data,size_t len){char h[512];const char*m=status==200?"OK":status==400?"Bad Request":status==404?"Not Found":status==409?"Conflict":"Server Error";int n=snprintf(h,sizeof h,"HTTP/1.1 %d %s\r\nContent-Type: %s\r\nContent-Length: %zu\r\nCache-Control: no-store\r\nConnection: close\r\n\r\n",status,m,type,len);send(fd,h,(size_t)n,0);while(len){ssize_t s=send(fd,data,len,0);if(s<=0)break;data+=s;len-=(size_t)s;}}
static void send_json(int fd,int status,const char*j){send_response(fd,status,"application/json",j,strlen(j));}
static void send_file(int fd,const char*path,const char*type){FILE*f=fopen(path,"rb");if(!f){send_json(fd,404,"{\"error\":\"File not found\"}");return;}if(fseek(f,0,SEEK_END)){fclose(f);send_json(fd,500,"{\"error\":\"File read failed\"}");return;}long z=ftell(f);rewind(f);if(z<0||z>5000000){fclose(f);send_json(fd,500,"{\"error\":\"Invalid file size\"}");return;}char*d=malloc((size_t)z+1);if(!d){fclose(f);send_json(fd,500,"{\"error\":\"Out of memory\"}");return;}size_t n=fread(d,1,(size_t)z,f);fclose(f);send_response(fd,200,type,d,n);free(d);}
static void update_engine(void){if(engine_pid>0){int st;pid_t r=waitpid(engine_pid,&st,WNOHANG);if(r==engine_pid||(r<0&&errno==ECHILD))engine_pid=-1;}}
static int is_running(void){update_engine();return engine_pid>0;}
static int get_int(const char*b,const char*k,int def,int min,int max){char pat[80];snprintf(pat,sizeof pat,"\"%s\"",k);const char*p=strstr(b,pat);if(!p)return def;p=strchr(p,':');if(!p)return def;p++;while(*p==' '||*p=='\t')p++;char*e;long v=strtol(p,&e,10);if(e==p||v<min||v>max)return def;return (int)v;}
static void start_engine(int fd,const char*body){if(is_running()){send_json(fd,409,"{\"error\":\"A test is already running\"}");return;}int wv=get_int(body,"workers",2,1,8),mv=get_int(body,"memory",128,0,512),dv=get_int(body,"duration",15,5,60);char w[16],m[16],d[16];snprintf(w,sizeof w,"%d",wv);snprintf(m,sizeof m,"%d",mv);snprintf(d,sizeof d,"%d",dv);remove(csv_file);pid_t p=fork();if(p<0){send_json(fd,500,"{\"error\":\"Could not start C engine\"}");return;}if(p==0){int nf=open("/dev/null",O_WRONLY);if(nf>=0){dup2(nf,1);dup2(nf,2);close(nf);}execl("./stress_engine","stress_engine","--workers",w,"--memory",m,"--duration",d,"--csv",csv_file,(char*)NULL);_exit(127);}engine_pid=p;send_json(fd,200,"{\"success\":true,\"running\":true}");}
static void stop_engine(int fd){if(is_running()){kill(engine_pid,SIGTERM);int st;while(waitpid(engine_pid,&st,0)<0&&errno==EINTR){}engine_pid=-1;}send_json(fd,200,"{\"success\":true,\"running\":false}");}
static void status_engine(int fd){char json[BUF_SIZE],samples[10000]="";int count=0;double latest_cpu=0,latest_ram=0,peak_cpu=0,peak_ram=0;double used_mb=0,available_mb=0,total_mb=0;int last_second=0;FILE*f=fopen(csv_file,"r");if(f){char line[512];(void)fgets(line,sizeof line,f);while(fgets(line,sizeof line,f)&&count<60){int sec;double cpu,ram;unsigned long long used=0,avail=0;int got=sscanf(line,"%d,%lf,%lf,%llu,%llu",&sec,&cpu,&ram,&used,&avail);if(got<3)continue;char item[180];int n=snprintf(item,sizeof item,"%s{\"second\":%d,\"elapsed\":%d,\"cpu\":%.2f,\"ram\":%.2f}",count?",":"",sec,sec,cpu,ram);if(n<0||strlen(samples)+(size_t)n>=sizeof samples)break;strcat(samples,item);last_second=sec;latest_cpu=cpu;latest_ram=ram;if(cpu>peak_cpu)peak_cpu=cpu;if(ram>peak_ram)peak_ram=ram;if(got>=5){used_mb=(double)used;available_mb=(double)avail;}count++;}fclose(f);}struct sysinfo si;if(sysinfo(&si)==0){double unit=(double)si.mem_unit/(1024.0*1024.0);total_mb=(double)si.totalram*unit;if(count==0||used_mb==0){used_mb=((double)si.totalram-(double)si.freeram-(double)si.bufferram)*unit;available_mb=((double)si.freeram+(double)si.bufferram)*unit;}if(used_mb<0)used_mb=0;if(available_mb<0)available_mb=0;}char config[200];snprintf(config,sizeof config,"\"workers\":2,\"memory\":128,\"duration\":15");snprintf(json,sizeof json,"{\"running\":%s,\"cpu\":%.2f,\"ram\":%.2f,\"peak_cpu\":%.2f,\"peak_ram\":%.2f,\"used_mb\":%.0f,\"available_mb\":%.0f,\"total_mb\":%.0f,\"samples_count\":%d,\"samples\":[%s],\"has_csv\":%s,\"latest\":{\"cpu\":%.2f,\"ram\":%.2f,\"used\":%.0f,\"available\":%.0f},\"config\":{%s}}",is_running()?"true":"false",latest_cpu,latest_ram,peak_cpu,peak_ram,used_mb,available_mb,total_mb,count,samples,count?"true":"false",latest_cpu,latest_ram,used_mb,available_mb,config);(void)last_second;send_json(fd,200,json);}
static void handle_client(int fd){char b[BUF_SIZE+1];ssize_t n=recv(fd,b,BUF_SIZE,0);if(n<=0)return;b[n]='\0';char method[16]="",path[256]="";sscanf(b,"%15s %255s",method,path);char*body=strstr(b,"\r\n\r\n");body=body?body+4:"";if(!strcmp(method,"GET")){if(!strcmp(path,"/"))send_file(fd,"templates/index.html","text/html; charset=utf-8");else if(!strcmp(path,"/static/style.css"))send_file(fd,"static/style.css","text/css");else if(!strcmp(path,"/static/app.js"))send_file(fd,"static/app.js","application/javascript");else if(!strcmp(path,"/api/status"))status_engine(fd);else if(!strcmp(path,"/api/download"))send_file(fd,csv_file,"text/csv");else send_json(fd,404,"{\"error\":\"Not found\"}");}else if(!strcmp(method,"POST")){if(!strcmp(path,"/api/start"))start_engine(fd,body);else if(!strcmp(path,"/api/stop"))stop_engine(fd);else send_json(fd,404,"{\"error\":\"Not found\"}");}else send_json(fd,400,"{\"error\":\"Unsupported request\"}");}
static void cleanup(int sig){(void)sig;if(engine_pid>0){kill(engine_pid,SIGTERM);int st;while(waitpid(engine_pid,&st,0)<0&&errno==EINTR){}}_exit(0);}
int main(void){signal(SIGINT,cleanup);signal(SIGTERM,cleanup);signal(SIGPIPE,SIG_IGN);int s=socket(AF_INET,SOCK_STREAM,0);if(s<0){perror("socket");return 1;}int opt=1;setsockopt(s,SOL_SOCKET,SO_REUSEADDR,&opt,sizeof opt);struct sockaddr_in a={0};a.sin_family=AF_INET;a.sin_port=htons(PORT);a.sin_addr.s_addr=htonl(INADDR_LOOPBACK);if(bind(s,(struct sockaddr*)&a,sizeof a)<0){perror("bind");close(s);return 1;}if(listen(s,10)<0){perror("listen");close(s);return 1;}printf("\nOS STRESSLAB - C SERVER\nWebsite: http://127.0.0.1:%d\nBackend language: C\nStress engine: C\nMemory telemetry: enabled\nPress Ctrl+C to stop.\n\n",PORT);fflush(stdout);for(;;){int c=accept(s,NULL,NULL);if(c<0){if(errno==EINTR)continue;perror("accept");break;}handle_client(c);close(c);}close(s);return 0;}
